import { Box, Container, Stack, Typography } from "@mui/material";
import BlocksText from "../components/BlocksText";
import { mediaUrl } from "../services/api";
import type { HomeExplore } from "../types/home";
import exploreBg from "../assets/explore-banner.webp";

export default function ExploreDevices({ data }: { data?: HomeExplore | null }) {
  if (!data) return null;

  const background = mediaUrl(data.background) || exploreBg;
  const image = mediaUrl(data.image);

  return (
    <Box
      sx={{
        backgroundColor: "#3d5a9a",
        backgroundImage: `url(${background})`,
        backgroundSize: "cover",
        backgroundPosition: "center",
        backgroundRepeat: "no-repeat",
        py: { xs: 3, sm: 4, md: 8, lg: 10, tv: 12 },
      }}
    >
      <Container
        maxWidth={false}
        sx={{
          maxWidth: { xs: "100%", md: 1140, lg: 1280, xl: 1440, tv: 1680 },
          px: { xs: 2, sm: 3, md: 4, lg: 5, tv: 8 },
        }}
      >
        <Stack
          direction={{ xs: "column", md: "row" }}
          alignItems="center"
          justifyContent="space-around"
          flexWrap={{ xs: "wrap", lg: "nowrap" }}
          spacing={{ xs: 3, sm: 3.5, md: 4, lg: 6, tv: 8 }}
        >
          <Box sx={{ flex: { md: "1 1 42%" }, width: "100%", maxWidth: { md: 520, lg: 560, tv: 640 } }}>
            <Typography
              sx={{
                color: "#fff",
                fontSize: { xs: 22, sm: 28, md: 36, lg: 48, tv: 56 },
                fontWeight: 700,
                lineHeight: 1.2,
                mb: { xs: 1.5, md: 2 },
              }}
            >
              {data.title}
            </Typography>
            <BlocksText
              content={data.description}
              sx={{
                color: "rgba(255,255,255,0.8)",
                fontSize: { xs: 14, sm: 16, md: 18, tv: 20 },
                fontWeight: 400,
                lineHeight: { xs: 1.6, md: "28px" },
                "& strong": { fontWeight: 700, color: "#fff" },
                "& p": { mb: 0, color: "inherit" },
              }}
            />
          </Box>
          {image ? (
            <Box
              sx={{
                flex: { md: "1 1 55%" },
                width: "100%",
                display: "flex",
                justifyContent: "center",
                py: { xs: 1, md: 2, lg: 4 },
              }}
            >
              <Box
                component="img"
                src={image}
                alt={data.image?.alternativeText || data.title || "Explore"}
                sx={{
                  width: { xs: "100%", sm: "90%", md: "80%" },
                  maxWidth: { xs: 320, sm: 480, md: 700, lg: 863, tv: 980 },
                  height: "auto",
                  display: "block",
                }}
              />
            </Box>
          ) : null}
        </Stack>
      </Container>
    </Box>
  );
}
